    def get_inbound_shipment_suppliers(self, first_loop, inbounds):
        page = 1
        suppliers = []
        while True:
            params = {"page": page, "per_page": PAGE_SIZE}
            rsp = self.zoho_request("contacts", params=params)
            contacts = rsp["contacts"]
            for contact in contacts:
                if contact["contact_type"] != "vendor":
                    continue
                formatted_supplier = {
                    "id": str(contact["contact_id"]),
                    "name": contact["contact_name"],
                    "warehouse_customer_id": None,
                    "additional_fields": {},
                }
                suppliers.append(formatted_supplier)
